ALTER TABLE "enrollments" ADD COLUMN "contact_round" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
UPDATE "enrollments" e SET "contact_round" = r.n FROM (SELECT id, row_number() OVER (PARTITION BY company_id ORDER BY created_at, id) AS n FROM "enrollments") r WHERE r.id = e.id AND r.n > 1;--> statement-breakpoint
CREATE VIEW "public"."contact_outcomes" AS (WITH sent AS ( SELECT m.enrollment_id, max(m.sent_at) AS last_sent_at FROM messages m WHERE m.state::text = 'sent'::text GROUP BY m.enrollment_id ), ev AS ( SELECT te.enrollment_id, max(te.received_at) AS last_event_at, bool_or(te.kind::text = ANY (ARRAY['unsubscribe'::text, 'complaint'::text])) AS opted_out, bool_or(te.kind::text = 'reply'::text AND (te.disposition::text = ANY (ARRAY['interested'::text, 'meeting_booked'::text]))) AS warm, COALESCE((array_agg(COALESCE(te.disposition::text, 'other'::text) ORDER BY te.received_at DESC, te.id DESC) FILTER (WHERE te.kind::text = 'reply'::text))[1] = 'other'::text, false) AS needs_a_look, bool_or(te.kind::text = 'bounce'::text AND te.bounce_class::text = 'hard'::text) AS hard_bounced, (array_agg(te.disposition ORDER BY te.received_at DESC, te.id DESC) FILTER (WHERE te.kind::text = 'reply'::text AND te.disposition IS NOT NULL))[1] AS disposition FROM thread_events te GROUP BY te.enrollment_id ) SELECT e.id AS enrollment_id, e.company_id, e.niche, e.sequence_name, e.offer, e.to_email, e.contact_round, e.created_at AS enrolled_at, GREATEST(e.created_at, e.stopped_at, s.last_sent_at, ev.last_event_at) AS last_touch_at, CASE WHEN e.state::text = 'active'::text THEN 'active'::text WHEN (e.stop_reason::text = ANY (ARRAY['opt_out'::text, 'complaint'::text])) OR ev.opted_out THEN 'opted_out'::text WHEN ev.warm THEN 'warm'::text WHEN e.stop_reason::text = 'manual'::text THEN 'stopped_by_hand'::text WHEN ev.needs_a_look THEN 'needs_a_look'::text WHEN ev.disposition::text = ANY (ARRAY['not_interested'::text, 'not_now'::text, 'wrong_person'::text, 'referral'::text]) THEN ev.disposition::text WHEN e.stop_reason::text = 'bounce'::text OR ev.hard_bounced THEN 'bounced'::text ELSE 'no_reply'::text END AS outcome FROM enrollments e LEFT JOIN sent s ON s.enrollment_id = e.id LEFT JOIN ev ON ev.enrollment_id = e.id);--> statement-breakpoint
-- Replaced in place, columns appended at the end: reply_by_evidence reads enrollment_outcomes.
CREATE OR REPLACE VIEW "public"."campaign_funnel" AS (WITH sends AS ( SELECT m.enrollment_id, count(*) FILTER (WHERE m.step = 0) AS openers_sent, count(*) FILTER (WHERE m.step > 0) AS followups_sent FROM messages m WHERE m.state::text = 'sent'::text GROUP BY m.enrollment_id ), inbound AS ( SELECT te.enrollment_id, count(*) FILTER (WHERE te.kind::text = 'reply'::text) AS replies, count(*) FILTER (WHERE te.disposition::text = ANY (ARRAY['interested'::character varying, 'meeting_booked'::character varying]::text[])) AS interested, count(*) FILTER (WHERE te.kind::text = 'auto_reply'::text) AS auto_replies, count(*) FILTER (WHERE te.kind::text = 'bounce'::text AND te.bounce_class::text = 'hard'::text) AS hard_bounces, count(*) FILTER (WHERE te.kind::text = 'unsubscribe'::text) AS unsubscribes FROM thread_events te GROUP BY te.enrollment_id ) SELECT e.niche, e.sequence_name, e.kind AS enrollment_kind, count(*) AS enrolled, count(*) FILTER (WHERE e.state::text = 'active'::text) AS active, count(*) FILTER (WHERE e.state::text = 'finished'::text) AS finished, count(*) FILTER (WHERE e.stop_reason::text = 'reply'::text) AS stopped_reply, count(*) FILTER (WHERE e.stop_reason::text = 'bounce'::text) AS stopped_bounce, count(*) FILTER (WHERE e.stop_reason::text = 'opt_out'::text) AS stopped_opt_out, count(*) FILTER (WHERE e.stop_reason::text = 'complaint'::text) AS stopped_complaint, count(*) FILTER (WHERE e.stop_reason::text = 'manual'::text) AS stopped_manual, COALESCE(sum(sends.openers_sent), 0::numeric) AS openers_sent, COALESCE(sum(sends.followups_sent), 0::numeric) AS followups_sent, COALESCE(sum(inbound.replies), 0::numeric) AS replies, COALESCE(sum(inbound.interested), 0::numeric) AS interested, COALESCE(sum(inbound.auto_replies), 0::numeric) AS auto_replies, COALESCE(sum(inbound.hard_bounces), 0::numeric) AS hard_bounces, COALESCE(sum(inbound.unsubscribes), 0::numeric) AS unsubscribes, e.contact_round > 1 AS recycled FROM enrollments e LEFT JOIN sends ON sends.enrollment_id = e.id LEFT JOIN inbound ON inbound.enrollment_id = e.id GROUP BY e.niche, e.sequence_name, e.kind, (e.contact_round > 1));--> statement-breakpoint
CREATE OR REPLACE VIEW "public"."enrollment_outcomes" AS (WITH opener AS ( SELECT m.enrollment_id, m.template AS opener_template, m.template_version AS opener_template_version, m.state AS opener_state, m.provenance -> 'address'::text AS address FROM messages m WHERE m.step = 0 ), sends AS ( SELECT m.enrollment_id, count(*) FILTER (WHERE m.state::text = 'sent'::text) AS steps_sent, min(m.sent_at) AS first_sent_at, max(m.sent_at) AS last_sent_at FROM messages m GROUP BY m.enrollment_id ), events AS ( SELECT te.enrollment_id, count(*) FILTER (WHERE te.kind::text = 'reply'::text) AS replies, bool_or(te.kind::text = 'reply'::text) AS replied, bool_or(te.kind::text = 'reply'::text AND (te.disposition::text = ANY (ARRAY['interested'::character varying, 'meeting_booked'::character varying]::text[]))) AS interested, bool_or(te.kind::text = 'bounce'::text AND te.bounce_class::text = 'hard'::text) AS hard_bounced, bool_or(te.kind::text = 'bounce'::text AND te.bounce_class::text = 'soft'::text) AS soft_bounced, bool_or(te.kind::text = 'unsubscribe'::text) AS unsubscribed, bool_or(te.kind::text = 'complaint'::text) AS complained, bool_or(te.kind::text = 'auto_reply'::text) AS auto_replied, min(te.received_at) FILTER (WHERE te.kind::text = 'reply'::text) AS first_reply_at, (array_agg(te.disposition ORDER BY te.received_at DESC, te.id DESC) FILTER (WHERE te.kind::text = 'reply'::text AND te.disposition IS NOT NULL))[1] AS disposition FROM thread_events te GROUP BY te.enrollment_id ) SELECT e.id AS enrollment_id, e.niche, e.sequence_name, e.kind AS enrollment_kind, e.company_id, e.person_id, e.to_email, e.sender, e.state, e.stop_reason, e.created_at AS enrolled_at, o.opener_template, o.opener_template_version, o.opener_state, o.address ->> 'evidence'::text AS evidence, o.address ->> 'verification_result'::text AS verification_result, o.address ->> 'pick_method'::text AS pick_method, (o.address ->> 'lead_id'::text)::integer AS lead_id, (o.address ->> 'candidate_id'::text)::integer AS candidate_id, (o.address ->> 'document_id'::text)::integer AS source_document_id, o.address ->> 'source_url'::text AS source_url, COALESCE(s.steps_sent, 0::bigint) AS steps_sent, s.first_sent_at, s.last_sent_at, COALESCE(ev.replies, 0::bigint) AS replies, COALESCE(ev.replied, false) AS replied, COALESCE(ev.interested, false) AS interested, ev.disposition, COALESCE(ev.hard_bounced, false) AS hard_bounced, COALESCE(ev.soft_bounced, false) AS soft_bounced, COALESCE(ev.unsubscribed, false) AS unsubscribed, COALESCE(ev.complained, false) AS complained, COALESCE(ev.auto_replied, false) AS auto_replied, ev.first_reply_at, e.contact_round FROM enrollments e LEFT JOIN opener o ON o.enrollment_id = e.id LEFT JOIN sends s ON s.enrollment_id = e.id LEFT JOIN events ev ON ev.enrollment_id = e.id);